function v8Esc(s){return typeof e==='function'?e(s):String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function v8Letter(i){return String.fromCharCode(97+i)+')'}
function v8TypeFromLesson(t,s){const id=(s.id||'').toLowerCase(), title=(s.title||'').toLowerCase(), tid=(t.id||'').toLowerCase();
 const direct={'present-simple':'present-simple','present-continuous':'present-continuous','present-perfect':'present-perfect','present-perfect-continuous':'present-perfect-continuous','past-simple':'past-simple','past-continuous':'past-continuous','past-perfect':'past-perfect','past-perfect-continuous':'past-perfect-continuous','future-simple':'future-will','future-plans':'going-to','future-continuous':'future-continuous','future-perfect':'future-perfect','future-perfect-continuous':'future-perfect-continuous'};
 if(direct[id])return direct[id];
 if(tid==='passive'||/bị động|passive/.test(title))return 'passive';
 if(tid==='reported-speech'||/tường thuật|reported/.test(title))return 'reported';
 if(tid==='relative-clauses'||/quan hệ|relative/.test(title))return 'relative';
 if(tid==='conditionals'||/điều kiện|conditional|wish/.test(title))return 'conditionals';
 if(tid==='modals'||/khuyết thiếu|modal/.test(title))return 'modals';
 if(tid==='gerunds-infinitives'||/danh động từ|nguyên mẫu|gerund|infinitive/.test(title))return 'gerunds';
 if(tid==='articles'||/mạo từ|article/.test(title))return 'articles';
 if(tid==='prepositions'||/giới từ|preposition/.test(title))return 'prepositions';
 if(tid==='comparison'||/so sánh|tính từ|trạng từ|adjective|adverb/.test(title))return 'adjadv';
 if(tid==='tag-questions'||/câu hỏi|question/.test(title))return 'questions';
 if(tid==='quantifiers'||/số lượng|some|any|much|many|few|little/.test(title))return 'quantifiers';
 if(tid==='phrasal-verbs'||/cụm động từ|phrasal/.test(title))return 'phrasal';
 return 'general';}
function v8UnitType(u){const title=(u.title||'').toLowerCase(), c=(u.category||'').toLowerCase();
 if(/present perfect continuous/.test(title))return 'present-perfect-continuous';
 if(/present continuous/.test(title))return 'present-continuous';
 if(/present perfect/.test(title))return 'present-perfect';
 if(/present simple/.test(title))return 'present-simple';
 if(/past perfect continuous/.test(title))return 'past-perfect-continuous';
 if(/past perfect/.test(title))return 'past-perfect';
 if(/past continuous/.test(title))return 'past-continuous';
 if(/past simple/.test(title))return 'past-simple';
 if(/future perfect continuous|will have been doing/.test(title))return 'future-perfect-continuous';
 if(/future continuous|will be doing/.test(title))return 'future-continuous';
 if(/future perfect|will have done/.test(title))return 'future-perfect';
 if(/going to/.test(title))return 'going-to';
 if(/will|shall|future/.test(title)&&!/(reported|modal)/.test(title))return 'future-will';
 if(/passive|is done|was done|being done|been done/.test(title)||c==='passive')return 'passive';
 if(/reported|reporting|said|told/.test(title)||c==='reported-speech')return 'reported';
 if(/relative|who|which|where|whose/.test(title)||c==='relative-clauses')return 'relative';
 if(/if|condition|wish|unless|provided/.test(title)||c==='conditionals')return 'conditionals';
 if(/modal|can|could|may|might|must|should|ought|need/.test(title)||c==='modals')return 'modals';
 if(/verb\+|infinitive|gerund|\b-ing\b/.test(title)||c==='gerunds-infinitives')return 'gerunds';
 if(/article|a\/an|zero article/.test(title)||c==='articles')return 'articles';
 if(/preposition|at\/on\/in|in\/at\/on/.test(title)||c==='prepositions')return 'prepositions';
 if(/comparison|superlative|adjective|adverb|so and such|enough|too/.test(title)||c==='comparison')return 'adjadv';
 if(/question|auxiliary|tag/.test(title)||c==='tag-questions')return 'questions';
 if(/some|any|much|many|few|little|all|both|each|every|no\/none/.test(title)||c==='quantifiers')return 'quantifiers';
 if(/phrasal/.test(title)||c==='phrasal-verbs')return 'phrasal';
 return 'general';}
function v8ExampleHtml(examples){return (examples||[]).map(x=>`<div class="v8-mini-example"><b>${v8Esc(x[0]||x.en||'')}</b><span>${v8Esc(x[1]||x.vi||'')}</span></div>`).join('')}
function v8UseItems(type, rawUses, examples){
 if(V8_TENSES[type])return V8_TENSES[type].uses;
 const uses=(rawUses||[]).filter(Boolean);
 const ex=(examples||[]).filter(Boolean);
 const fallback=V8_GENERIC_USES[type]||uses.length?uses:['Dùng cấu trúc này khi cần diễn đạt đúng chức năng ngữ pháp được nêu trong tên bài.'];
 const source=uses.length?uses:(V8_GENERIC_USES[type]||fallback);
 return source.map((x,i)=>({title:String(x).replace(/^Dùng\s+/i,'').replace(/\.$/,''),desc:`Dùng cấu trúc của bài khi câu cần diễn tả ${String(x).toLowerCase().replace(/\.$/,'')}. Hãy đọc nghĩa cả câu trước rồi mới chọn dạng từ hoặc trật tự câu.`,examples:ex.length?[[ex[i%ex.length].en||'',ex[i%ex.length].vi||'']]:[]}));
}
function v8RenderUses(items){return `<div class="v8-use-list">${items.map((x,i)=>`<article class="v8-use-item"><div class="v8-use-head"><span class="v8-use-letter">${v8Letter(i)}</span><h4 class="v8-use-title">${v8Esc(x.title)}</h4></div><p class="v8-use-desc">${v8Esc(x.desc||'')}</p><div class="v8-use-examples">${v8ExampleHtml(x.examples)}</div></article>`).join('')}</div>`}
function v8RenderFormulaCards(cards){return `<div class="v8-formula-grid">${cards.map((c,i)=>`<article class="v8-formula-card ${cards.length<3?'wide':''}"><div class="v8-formula-title">${v8Esc(c.title)}</div><div class="v8-formula-body"><div class="v8-formula">${v8Esc(c.formula).replace(/\n/g,'<br>')}</div>${c.notes&&c.notes.length?`<ul class="v8-formula-notes">${c.notes.map(n=>`<li>${v8Esc(n)}</li>`).join('')}</ul>`:''}<div class="v8-formula-examples">${(c.examples||[]).map(x=>`<div class="v8-formula-example"><b>${v8Esc(x[0])}</b><span>${v8Esc(x[1])}</span></div>`).join('')}</div></div></article>`).join('')}</div>`}
function v8RenderGuideStructures(s,type){
 if(V8_TENSES[type])return v8RenderFormulaCards(V8_TENSES[type].structures);
 const groups=s&&s.guide&&Array.isArray(s.guide.structures)?s.guide.structures:[];
 if(groups.length)return `<div class="v8-formula-grid">${groups.map(g=>`<article class="v8-formula-card wide"><div class="v8-formula-title">${v8Esc(g.title)}</div><div class="v8-formula-body"><div class="v8-structure-table"><table><thead><tr>${(g.headers||[]).map(h=>`<th>${v8Esc(h)}</th>`).join('')}</tr></thead><tbody>${(g.rows||[]).map(r=>`<tr>${r.map(c=>`<td>${v8Esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${g.note?`<div class="v8-structure-note">${v8Esc(g.note)}</div>`:''}</div></article>`).join('')}</div>`;
 const rows=V8_GENERIC_ROWS[type]||[['Mẫu câu chính',s.formula||'Xem ví dụ và xác định vị trí từng thành phần trong câu.',(s.examples&&s.examples[0]&&s.examples[0].en)||'']];
 return v8RenderGenericRows(rows);
}
function v8RenderGenericRows(rows){return `<div class="v8-structure-table"><table><thead><tr><th>Loại câu / chức năng</th><th>Cấu trúc hoặc cách dùng</th><th>Ví dụ</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${v8Esc(r[0])}</b></td><td>${v8Esc(r[1])}</td><td>${v8Esc(r[2])}</td></tr>`).join('')}</tbody></table></div>`}
function v8SignalData(type,markers){if(V8_TENSES[type])return V8_TENSES[type].signals;const list=(markers||[]).filter(Boolean);const generic=V8_GENERIC_SIGNALS[type]||[];const items=list.length?list:generic;return items.length?[{title:type==='general'?'Từ khóa hoặc dấu hiệu thường gặp':'Từ khóa / điểm cần chú ý',items,example:''}]:[]}
function v8RenderSignals(groups){return `<div class="v8-signal-groups">${groups.map((g,i)=>`<article class="v8-signal-group"><div class="v8-signal-head">${v8Letter(i)} ${v8Esc(g.title)}</div><div class="v8-signal-items">${(g.items||[]).map(x=>`<span class="v8-signal-chip">${v8Esc(x)}</span>`).join('')}</div>${g.example?`<div class="v8-signal-example">${v8Esc(g.example)}</div>`:''}</article>`).join('')}</div>`}
function v8SourceLinks(type){const links=[['Cambridge Grammar Today','https://dictionary.cambridge.org/grammar/british-grammar/'],['British Council LearnEnglish','https://learnenglish.britishcouncil.org/free-resources/grammar']];if(type==='present-continuous')links.unshift(['Lời Giải Hay: Thì hiện tại tiếp diễn',V8_LOIGIAIHAY]);return links.map(x=>`<a target="_blank" rel="noopener" href="${v8Esc(x[1])}">${v8Esc(x[0])}</a>`).join('')}

window.renderLesson=function(){
 const t=topicById(state.topic),s=subById(t.id,state.lesson),type=v8TypeFromLesson(t,s),kg=s.kidGuide||{},lessonQs=QUESTIONS.filter(q=>q.topic===t.id&&q.sub===s.id);
 const uses=v8UseItems(type,kg.whenUse||s.uses||s.use||[],s.examples||[]),signals=v8SignalData(type,s.markers||[]);
 let n=1;
 let html=`<section class="lesson-hero"><span class="eyebrow">Chuyên đề ${String(t.no).padStart(2,'0')} · ${v8Esc(t.level)}</span><h2>${v8Esc(s.title)}</h2><p>${v8Esc(s.summary||kg.why||t.overview)}</p><div class="actions"><a class="btn warn" target="_blank" href="${v8Esc(s.video||'https://www.youtube.com/results?search_query=English+grammar+Vietnamese')}">Video YouTube</a><button class="btn primary" data-start-topic="${t.id}" data-start-lesson="${s.id}">Luyện bài này (${lessonQs.length} câu)</button></div></section>`;
 html+=`<section class="card"><h3 class="section-title">${n++}. Khi nào dùng?</h3><p class="v8-section-intro">Mỗi cách dùng được tách thành một mục riêng. Đọc ý nghĩa và ví dụ trước khi học công thức.</p>${v8RenderUses(uses)}</section>`;
 html+=`<section class="card"><h3 class="section-title">${n++}. Cấu trúc câu / mẫu câu</h3><p class="v8-section-intro">Phần này luôn được hiển thị để em biết chính xác vị trí chủ ngữ, trợ động từ và động từ chính.</p>${v8RenderGuideStructures(s,type)}</section>`;
 if(signals.length)html+=`<section class="card"><h3 class="section-title">${n++}. ${V8_TENSES[type]?'Dấu hiệu nhận biết':'Từ khóa và điểm cần chú ý'}</h3>${v8RenderSignals(signals)}</section>`;
 html+=`<section class="card"><h3 class="section-title">${n++}. Ví dụ có dịch nghĩa</h3>${(s.examples||[]).slice(0,6).map(x=>`<div class="example"><b>${v8Esc(x.en)}</b><br><span>${v8Esc(x.vi)}</span>${x.note?`<br><small>${v8Esc(x.note)}</small>`:''}</div>`).join('')||'<div class="example">Hãy xem ví dụ trong phần cấu trúc câu ở trên.</div>'}</section>`;
 html+=`<section class="card"><h3 class="section-title">${n++}. So sánh và bẫy dễ sai</h3><p>${v8Esc(s.contrast||'So sánh cấu trúc này với các bài gần nó trong cùng chuyên đề để tránh nhầm dạng câu.')}</p><div class="trap"><b>Exam Trap:</b> ${v8Esc((s.traps&&s.traps[0])||s.trap||kg.easyMemory||'Không chọn đáp án chỉ vì một từ khóa.')}</div></section>`;
 html+=`<section class="sourcebox"><b>Nguồn sách:</b> ${v8Esc(s.refs||s.sources||t.sources)}<br><b>Nguồn giải thích bổ sung:</b> ${v8SourceLinks(type)}</section>`;
 document.querySelector('#lesson-area').innerHTML=html;
};

function v8Find(uid){for(const b of V7_SOURCE_BOOKS){let u=(b.units||[]).find(x=>x.uid===uid);if(u)return {...u,_kind:'unit'};u=(b.supplements||[]).find(x=>x.uid===uid);if(u)return {...u,bookId:b.id,bookTitle:b.title,_kind:'supplement'}}return null}
function v8Clean(s){return String(s||'').replace(/\n{3,}/g,'\n\n').trim()}
function v8UnitUses(u,type){const raw=(u.uses||u.use||[]);const examples=[];return v8UseItems(type,raw.length?raw:(V8_GENERIC_USES[type]||[]),examples)}
function v8UnitStructures(type){if(V8_TENSES[type])return v8RenderFormulaCards(V8_TENSES[type].structures);return v8RenderGenericRows(V8_GENERIC_ROWS[type]||[['Mẫu câu chính','Đọc ví dụ của Unit, xác định từ/cụm từ thay đổi và giữ nguyên trật tự các thành phần còn lại.','Thay chủ ngữ và từ vựng để tự tạo câu mới.'],['Câu phủ định / câu hỏi','Kiểm tra trợ động từ, vị trí chủ ngữ và dạng động từ chính.','Sai thường nằm ở trợ động từ hoặc trật tự từ.'],['Cụm từ đi kèm','Ghi lại giới từ, collocation hoặc mẫu cố định xuất hiện trong Unit.','Học cả cụm, không dịch từng từ.']])}
function v8TheoryText(){return ''}

